/**
 * Highlights use the CSS Custom Highlight API: ranges are painted by the
 * browser without inserting a single element into the page, so frameworks
 * (React, Vue…) never see foreign nodes and the page's DOM, text offsets
 * and event handlers stay untouched. Styles live in highlights.css
 * (generated by scripts/build-extension.mjs from HIGHLIGHT_NAMES).
 *
 * Highlights can't receive events, so clicks and hovers are hit-tested
 * against the ranges' client rects.
 */

export const OTHER_HUES = [0, 22, 95, 125, 155, 180, 200, 222, 250, 278, 305, 335];

export type HighlightKind = 'own' | number; // number = index into OTHER_HUES

export function highlightName(kind: HighlightKind | 'draft', active: boolean, dark: boolean): string {
  const base = kind === 'own' ? 'mc-own' : kind === 'draft' ? 'mc-draft' : `mc-h${kind}`;
  return `${base}${active ? '-active' : ''}${dark ? '-d' : ''}`;
}

/** Every highlight name, for generating CSS and for cleanup. */
export function allHighlightNames(): string[] {
  const names: string[] = [];
  for (const dark of [false, true]) {
    for (const active of [false, true]) {
      names.push(highlightName('own', active, dark));
      OTHER_HUES.forEach((_, i) => names.push(highlightName(i, active, dark)));
    }
    names.push(highlightName('draft', false, dark));
  }
  return names;
}

/** Curius's name hash, bucketed into our palette. */
export function hueIndexFor(name: string): number {
  let a = 0;
  for (let i = 0; i < name.length; i++) a = (name.charCodeAt(i) + ((a << 5) - a)) | 0;
  return Math.abs(a) % OTHER_HUES.length;
}

export type HighlightItem = {
  threadId: string;
  range: Range;
  kind: HighlightKind;
  active: boolean;
};

type Cached = { item: HighlightItem; rects: DOMRect[] | null; rectsAt: number; length: number };

/** Hover hit-testing reuses geometry this long (clicks always measure fresh). */
const HOVER_CACHE_MS = 250;

export class Highlighter {
  private highlights = new Map<string, Highlight>();
  private items: Cached[] = [];
  readonly supported: boolean;

  constructor(private dark: boolean) {
    this.supported = typeof CSS !== 'undefined' && 'highlights' in CSS && typeof Highlight !== 'undefined';
    if (!this.supported) return;
    // Clear anything left by a previous (orphaned) instance of the extension.
    for (const name of allHighlightNames()) CSS.highlights.delete(name);
  }

  setDark(dark: boolean) {
    this.dark = dark;
  }

  private get(name: string, priority: number): Highlight {
    let h = this.highlights.get(name);
    if (!h) {
      h = new Highlight();
      h.priority = priority;
      this.highlights.set(name, h);
      CSS.highlights.set(name, h);
    }
    return h;
  }

  render(items: HighlightItem[], draft: Range | null) {
    this.items = items.map(item => ({ item, rects: null, rectsAt: 0, length: -1 }));
    if (!this.supported) return;
    for (const h of this.highlights.values()) h.clear();
    for (const { threadId: _t, range, kind, active } of items) {
      this.get(highlightName(kind, active, this.dark), active ? 2 : 1).add(range);
    }
    if (draft) this.get(highlightName('draft', false, this.dark), 3).add(draft);
  }

  /** Forget cached geometry (after scroll, resize or DOM changes). */
  invalidate() {
    for (const c of this.items) c.rects = null;
  }

  /**
   * The most specific highlighted thread under a viewport point. Layout can
   * change without any DOM mutation (CSS transforms, animations), so clicks
   * always re-measure; hover reuses very recent geometry.
   */
  hitTest(x: number, y: number, fresh = true): string | null {
    let best: Cached | null = null;
    let under: Element | null | undefined;
    const now = performance.now();
    for (const c of this.items) {
      if (fresh || !c.rects || now - c.rectsAt > HOVER_CACHE_MS) {
        c.rects = Array.from(c.item.range.getClientRects()).filter(r => r.width > 0 && r.height > 0);
        c.rectsAt = now;
      }
      const hit = c.rects.some(r => x >= r.left - 1 && x <= r.right + 1 && y >= r.top - 1 && y <= r.bottom + 1);
      if (!hit) continue;
      // The text must actually be what's under the pointer: rects also cover
      // text clipped by an overflow container or hidden under something else.
      under ??= document.elementFromPoint(x, y);
      if (!under || !c.item.range.intersectsNode(under)) continue;
      if (c.length < 0) c.length = c.item.range.toString().length;
      if (!best || c.length < best.length) best = c;
    }
    return best?.item.threadId ?? null;
  }

  destroy() {
    if (!this.supported) return;
    for (const name of this.highlights.keys()) CSS.highlights.delete(name);
    this.highlights.clear();
    this.items = [];
  }
}

/** Is the page dark? (Light text on a dark background.) */
export function pageIsDark(): boolean {
  const bg = (el: Element | null) => (el ? getComputedStyle(el).backgroundColor : '');
  const parse = (c: string) => {
    const m = /rgba?\(([\d.]+),\s*([\d.]+),\s*([\d.]+)(?:,\s*([\d.]+))?/.exec(c);
    if (!m) return null;
    const alpha = m[4] === undefined ? 1 : Number(m[4]);
    if (alpha < 0.5) return null;
    return [Number(m[1]), Number(m[2]), Number(m[3])];
  };
  const rgb = parse(bg(document.body)) ?? parse(bg(document.documentElement));
  if (!rgb) {
    // Transparent backgrounds: fall back to the text color.
    const fg = parse(document.body ? getComputedStyle(document.body).color : '');
    return fg ? luminance(fg) > 0.6 : false;
  }
  return luminance(rgb) < 0.35;
}

function luminance([r, g, b]: number[]): number {
  return (0.2126 * r + 0.7152 * g + 0.0722 * b) / 255;
}
